const e=JSON.parse('[{"id":"111_111010_001","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"在個案會談中，下列何者屬於開放性問題？\\n(A)請問你對於殺子後自殺這個問題有何看法\\n(B)你不會不好意思嗎\\n(C)你是不是覺得後悔\\n(D)你是對人生感到厭倦，所以才採取這麼激烈的手段，對不對","tableData":null,"images":[],"options":[{"key":"A","text":"請問你對於殺子後自殺這個問題有何看法","imageUrl":null},{"key":"B","text":"你不會不好意思嗎","imageUrl":null},{"key":"C","text":"你是不是覺得後悔","imageUrl":null},{"key":"D","text":"你是對人生感到厭倦，所以才採取這麼激烈的手段，對不對","imageUrl":null}],"correctAnswer":"A","explanation":"開放性問題不設限答題範圍或引導特定立場，能讓案主自由表達其個人看法與情感。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_002","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列何者不是反壓迫社會工作實務的原則？\\n(A)案主的問題是個人內在缺陷造成的\\n(B)案主的問題是遭遇創傷後的結果\\n(C)著重邊緣化的影響\\n(D)注意機構內部的管理原則","tableData":null,"images":[],"options":[{"key":"A","text":"案主的問題是個人內在缺陷造成的","imageUrl":null},{"key":"B","text":"案主的問題是遭遇創傷後的結果","imageUrl":null},{"key":"C","text":"著重邊緣化的影響","imageUrl":null},{"key":"D","text":"注意機構內部的管理原則","imageUrl":null}],"correctAnswer":"A","explanation":"反壓迫實務將問題視為社會結構或不平等造成的壓迫，而非歸咎於個人的內在缺陷。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_003","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"關於英國湯恩比館（Toynbee Hall）的慈善作法，下列敘述何者正確？\\n(A)成立於 1869 年\\n(B)倡議政府應介入貧民的救助工作\\n(C)將貧民分為值得幫助的與不值得幫助的兩種\\n(D)由中產階級、知識份子、社會改革者所主導","tableData":null,"images":[],"options":[{"key":"A","text":"成立於 1869 年","imageUrl":null},{"key":"B","text":"倡議政府應介入貧民的救助工作","imageUrl":null},{"key":"C","text":"將貧民分為值得幫助的與不值得幫助的兩種","imageUrl":null},{"key":"D","text":"由中產階級、知識份子、社會改革者所主導","imageUrl":null}],"correctAnswer":"D","explanation":"湯恩比館為睦鄰發展中心的先驅，由大學知識份子與社會改革者進駐貧民區，推動教育與社會改良。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_004","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"關於社會工作基本方法的敘述，下列何者錯誤？\\n(A)個案工作運用面對面的方式解決案主問題\\n(B)個案工作的對象為個人，不包括家庭\\n(C)團體工作是以團體為工具\\n(D)社會工作者在社區工作歷程中經常扮演倡導者的角色","tableData":null,"images":[],"options":[{"key":"A","text":"個案工作運用面對面的方式解決案主問題","imageUrl":null},{"key":"B","text":"個案工作的對象為個人，不包括家庭","imageUrl":null},{"key":"C","text":"團體工作是以團體為工具","imageUrl":null},{"key":"D","text":"社會工作者在社區工作歷程中經常扮演倡導者的角色","imageUrl":null}],"correctAnswer":"B","explanation":"社會個案工作的服務對象非常廣泛，除了個人之外，亦涵蓋家庭及周邊重要人際關係。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_005","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列何者符合格林伍德（Greenwood）對專業特質的定義？①有系統的理論知識 ②專業權威 ③社區認可 ④倫理守則 ⑤專利許可\\n(A)①②④⑤\\n(B)①②③⑤\\n(C)②③④⑤\\n(D)①②③④","tableData":null,"images":[],"options":[{"key":"A","text":"①②④⑤","imageUrl":null},{"key":"B","text":"①②③⑤","imageUrl":null},{"key":"C","text":"②③④⑤","imageUrl":null},{"key":"D","text":"①②③④","imageUrl":null}],"correctAnswer":"D","explanation":"格林伍德提出的專業屬性包含：理論體系、專業權威、社區認可、倫理守則以及專業文化。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_006","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關社會工作督導的意義與內涵，下列何者錯誤？\\n(A)督導是一種專業訓練方法，藉此傳授專業服務知識與技術\\n(B)督導是社會工作直接服務方法之一\\n(C)督導活動中的受督導者，在對象上可包括專職工作人員、新進人員、實習生\\n(D)督導功能主要包含行政、教育與支持","tableData":null,"images":[],"options":[{"key":"A","text":"督導是一種專業訓練方法，藉此傳授專業服務知識與技術","imageUrl":null},{"key":"B","text":"督導是社會工作直接服務方法之一","imageUrl":null},{"key":"C","text":"督導活動中的受督導者，在對象上可包括專職工作人員、新進人員、實習生","imageUrl":null},{"key":"D","text":"督導功能主要包含行政、教育與支持","imageUrl":null}],"correctAnswer":"B","explanation":"社會工作督導屬於行政與教育性的管理活動，被歸類為間接服務方法，而非直接服務。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_007","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"馬斯洛（Abraham Maslow）曾提出著名的「需求層次論」，認為人類的需求可分為五個層次，若從底層向上層推演，其順序應為何？①愛與隸屬的需求 ②生理的需求 ③自我實現的需求 ④安全的需求 ⑤尊重的需求\\n(A)②①③④⑤\\n(B)②①⑤④③\\n(C)②④①⑤③\\n(D)②④⑤③①","tableData":null,"images":[],"options":[{"key":"A","text":"②①③④⑤","imageUrl":null},{"key":"B","text":"②①⑤④③","imageUrl":null},{"key":"C","text":"②④①⑤③","imageUrl":null},{"key":"D","text":"②④⑤③①","imageUrl":null}],"correctAnswer":"C","explanation":"馬斯洛理論順序為：生理、安全、愛與隸屬、自尊、自我實現，對應序號為②④①⑤③。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_008","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"社會工作者為案主的權益與需求而辯護，這是屬於下列何種角色？\\n(A)教育角色\\n(B)諮詢角色\\n(C)治療角色\\n(D)倡導角色","tableData":null,"images":[],"options":[{"key":"A","text":"教育角色","imageUrl":null},{"key":"B","text":"諮詢角色","imageUrl":null},{"key":"C","text":"治療角色","imageUrl":null},{"key":"D","text":"倡導角色","imageUrl":null}],"correctAnswer":"D","explanation":"倡導者角色係指社會工作者代表案主發聲，爭取應有權益並協助其獲得必要的服務資源。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_009","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"社會工作者在服務過程中碰到有毒癮的青少年仍持續吸毒，卻欺騙社會工作者已經找到工作且再也沒有吸毒；但在一次個案會談中社會工作者發現案主的欺騙，一氣之下當場以不當言語辱罵案主。該社會工作者違反下列那一個專業價值？\\n(A)保密\\n(B)非批判的態度\\n(C)案主自決\\n(D)充權","tableData":null,"images":[],"options":[{"key":"A","text":"保密","imageUrl":null},{"key":"B","text":"非批判的態度","imageUrl":null},{"key":"C","text":"案主自決","imageUrl":null},{"key":"D","text":"充權","imageUrl":null}],"correctAnswer":"B","explanation":"社會工作者應保持客觀、中立，不應以個人情緒或道德觀對案主的行為進行情緒性的辱罵或評斷。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_010","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"成年未婚懷孕婦女對於「生下孩子」、「墮胎」、「出養」等決策猶豫不決。社會工作者應該如何協助案主進行決策？\\n(A)找出胎兒之父親，尊重其意見\\n(B)透過家族會議，進行決策\\n(C)請案主參酌同儕意見，進行決策\\n(D)協助案主釐清意見，充權案主解決問題的能量","tableData":null,"images":[],"options":[{"key":"A","text":"找出胎兒之父親，尊重其意見","imageUrl":null},{"key":"B","text":"透過家族會議，進行決策","imageUrl":null},{"key":"C","text":"請案主參酌同儕意見，進行決策","imageUrl":null},{"key":"D","text":"協助案主釐清意見，充權案主解決問題的能量","imageUrl":null}],"correctAnswer":"D","explanation":"秉持案主自決原則，社工應協助案主蒐集資訊與釐清思緒，賦予其能量以自行決定最適合的路徑。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_011","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"當社會工作者發現同事應服務對象生前之要求，在其過世後不告知家人便代為處理喪事。下列那一項作法不符合專業倫理？\\n(A)與該位同事討論與進行補救\\n(B)協助該位同事遮掩事件，以免傷害同儕關係與機構聲譽\\n(C)尋求機構主管的協助與介入\\n(D)透過社會工作師公會或相關專業組織採取介入行動","tableData":null,"images":[],"options":[{"key":"A","text":"與該位同事討論與進行補救","imageUrl":null},{"key":"B","text":"協助該位同事遮掩事件，以免傷害同儕關係與機構聲譽","imageUrl":null},{"key":"C","text":"尋求機構主管的協助與介入","imageUrl":null},{"key":"D","text":"透過社會工作師公會或相關專業組織採取介入行動","imageUrl":null}],"correctAnswer":"B","explanation":"專業倫理要求對不當行為進行監測與處理，隱瞞或遮掩同事的疏失違反了專業誠信與課責精神。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_012","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列何者狀況應尊重案主自我決定權？\\n(A)案主擬自傷\\n(B)21 歲未婚懷孕女性擬將孩子生下\\n(C)10 歲案主拒絕到校就學\\n(D)極重度智能障礙者擬購買機車","tableData":null,"images":[],"options":[{"key":"A","text":"案主擬自傷","imageUrl":null},{"key":"B","text":"21 歲未婚懷孕女性擬將孩子生下","imageUrl":null},{"key":"C","text":"10 歲案主拒絕到校就學","imageUrl":null},{"key":"D","text":"極重度智能障礙者擬購買機車","imageUrl":null}],"correctAnswer":"B","explanation":"具行為能力的成年案主在不危害他人與自身安全的情形下，應充分尊重其對個人生活的重大選擇。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_013","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"在災變時，為了救災必要，不需經當事人同意，強制拆除人民的設備或財產等作為洩洪等之需，依芮摩（Reamer）提出的處理倫理困境的對照原則，下列何者正確？\\n(A)傷害到維持人類性命、健康、尊嚴時優於傷害其他\\n(B)他人基本福祉權優於個人的自決權\\n(C)人們在自由意志下，遵守法律、機構規定等義務優於個人的信仰、價值和原則\\n(D)為了預防社會大眾傷害發生、為提升公共利益而對個人財產累積造成損害是可接受的","tableData":null,"images":[],"options":[{"key":"A","text":"傷害到維持人類性命、健康、尊嚴時優於傷害其他","imageUrl":null},{"key":"B","text":"他人基本福祉權優於個人的自決權","imageUrl":null},{"key":"C","text":"人們在自由意志下，遵守法律、機構規定等義務優於個人的信仰、價值和原則","imageUrl":null},{"key":"D","text":"為了預防社會大眾傷害發生、為提升公共利益而對個人財產累積造成損害是可接受的","imageUrl":null}],"correctAnswer":"D","explanation":"芮摩原則指出，為了保障公共安全與大眾利益，防止重大的公眾損害可優先於個人的財產權益。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_014","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"依據我國的社會工作師倫理守則，下列敘述何者錯誤？\\n(A)社會工作的服務紀錄應依法令及相關規範正確、客觀的記載\\n(B)社會工作師應具備社會工作專業技能，不斷充實自我\\n(C)社會工作師應致力社會福利政策的推展，增進福利服務效能，依情理公平進行福利給付與福利資源分配\\n(D)社會工作師接受教育、督導時應理性、自省，接納批評與建議","tableData":null,"images":[],"options":[{"key":"A","text":"社會工作的服務紀錄應依法令及相關規範正確、客觀的記載","imageUrl":null},{"key":"B","text":"社會工作師應具備社會工作專業技能，不斷充實自我","imageUrl":null},{"key":"C","text":"社會工作師應致力社會福利政策的推展，增進福利服務效能，依情理公平進行福利給付與福利資源分配","imageUrl":null},{"key":"D","text":"社會工作師接受教育、督導時應理性、自省，接納批評與建議","imageUrl":null}],"correctAnswer":"C","explanation":"資源分配應依據正義與公平原則（公正），而非單純依據情感或個人情理來決定。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_015","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關會談的敘述，下列何者正確？\\n(A)電話會談通常作為輔助性的會談媒介\\n(B)在會談室會談容易使得案主分心\\n(C)家訪會談比較能夠讓案主專心\\n(D)電話會談容易讓案主覺得不自在","tableData":null,"images":[],"options":[{"key":"A","text":"電話會談通常作為輔助性的會談媒介","imageUrl":null},{"key":"B","text":"在會談室會談容易使得案主分心","imageUrl":null},{"key":"C","text":"家訪會談比較能夠讓案主專心","imageUrl":null},{"key":"D","text":"電話會談容易讓案主覺得不自在","imageUrl":null}],"correctAnswer":"A","explanation":"電話會談常用於追蹤、預約或初步評估，作為正式面談之外的配套輔助溝通管道。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_016","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列何者不是形成社會工作直接服務過程「耗竭」的主要原因？\\n(A)案主的問題無法解決\\n(B)過度涉入案主的情境\\n(C)缺乏機構主管的支持\\n(D)個人生理機能衰退","tableData":null,"images":[],"options":[{"key":"A","text":"案主的問題無法解決","imageUrl":null},{"key":"B","text":"過度涉入案主的情境","imageUrl":null},{"key":"C","text":"缺乏機構主管的支持","imageUrl":null},{"key":"D","text":"個人生理機能衰退","imageUrl":null}],"correctAnswer":"D","explanation":"耗竭通常是由高壓力環境、情緒超載或工作體制不全引起，而非屬於自然的生理老化過程。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_017","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"「案主自決」是直接服務的倫理原則，當案主出現下列那些行為或特徵時，社會工作者可立即限制其自我決定的權利？①自殺行為 ②危害他人 ③患有輕度失智症 ④患有憂鬱症\\n(A)僅①②\\n(B)僅①②③\\n(C)僅①②④\\n(D)①②③④","tableData":null,"images":[],"options":[{"key":"A","text":"僅①②","imageUrl":null},{"key":"B","text":"僅①②③","imageUrl":null},{"key":"C","text":"僅①②④","imageUrl":null},{"key":"D","text":"①②③④","imageUrl":null}],"correctAnswer":"A","explanation":"當案主的決定涉及生命安全威脅（傷害自己或他人）時，基於保護生命價值，需限制其自決權。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_018","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關英國「社區照顧」概念的敘述，下列何者錯誤？\\n(A)強調去機構化\\n(B)以急性照顧為對象\\n(C)重視非正式照顧\\n(D)減少公共依賴","tableData":null,"images":[],"options":[{"key":"A","text":"強調去機構化","imageUrl":null},{"key":"B","text":"以急性照顧為對象","imageUrl":null},{"key":"C","text":"重視非正式照顧","imageUrl":null},{"key":"D","text":"減少公共依賴","imageUrl":null}],"correctAnswer":"B","explanation":"社區照顧主要針對需要長期支持的身心障礙者或老人，而非著重於短期醫療性質的急性照顧。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_019","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列何者為社區工作的意義？①一定的空間範圍 ②一群有共同生活特性的人群 ③有共同認同及關係的人群 ④具有相同職業的人群\\n(A)①②③\\n(B)①②④\\n(C)①③④\\n(D)②③④","tableData":null,"images":[],"options":[{"key":"A","text":"①②③","imageUrl":null},{"key":"B","text":"①②④","imageUrl":null},{"key":"C","text":"①③④","imageUrl":null},{"key":"D","text":"②③④","imageUrl":null}],"correctAnswer":"A","explanation":"社區的核心要素包含地理空間、共同的社會特徵以及人群間的相互連結與心理歸屬感。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_020","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"在社區參與的六個層次中，下列那一個是最高的社區參與層次？\\n(A)決策\\n(B)告知\\n(C)表達\\n(D)倡議與自我管理","tableData":null,"images":[],"options":[{"key":"A","text":"決策","imageUrl":null},{"key":"B","text":"告知","imageUrl":null},{"key":"C","text":"表達","imageUrl":null},{"key":"D","text":"倡議與自我管理","imageUrl":null}],"correctAnswer":"D","explanation":"倡議與自我管理代表社區成員能主動領導議題並掌握管理權，是參與程度中賦權層次最高的。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_021","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"當成員看到其他成員有相似遭遇的困擾，且對方能夠憑自己的力量站起來，這對所有成員均有正向的鼓勵作用，這是 Yalom 所謂的「注入希望」（instillation of hope）。下列何者不是注入希望的作用？\\n(A)知道／看到成員與我相似的問題得以解決\\n(B)看到其他成員的成功經驗而增加勇氣\\n(C)學到其他成員也和我一樣有不愉快的經驗\\n(D)看到團體幫助成員順利處理與我相像的問題而增加我的希望","tableData":null,"images":[],"options":[{"key":"A","text":"知道／看到成員與我相似的問題得以解決","imageUrl":null},{"key":"B","text":"看到其他成員的成功經驗而增加勇氣","imageUrl":null},{"key":"C","text":"學到其他成員也和我一樣有不愉快的經驗","imageUrl":null},{"key":"D","text":"看到團體幫助成員順利處理與我相像的問題而增加我的希望","imageUrl":null}],"correctAnswer":"C","explanation":"「學到他人也有不愉快經驗」屬於「普同感」的作用，而非強調成功可能性的「注入希望」。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_022","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關團體工作的類型，下列敘述何者錯誤？\\n(A)在醫院中由乳癌病人自發性所組成的團體屬於自助性團體\\n(B)會心團體強調分享此時此刻的當下經驗，以此增加個人人際的覺知與成長\\n(C)針對觀護所中的青少年所擬定之出院後生活計畫的團體是屬於社會化團體\\n(D)同性戀者聚在一起相互支持共同倡導與創造另一種生活型式的團體是屬於教育性團體","tableData":null,"images":[],"options":[{"key":"A","text":"在醫院中由乳癌病人自發性所組成的團體屬於自助性團體","imageUrl":null},{"key":"B","text":"會心團體強調分享此時此刻的當下經驗，以此增加個人人際的覺知與成長","imageUrl":null},{"key":"C","text":"針對觀護所中的青少年所擬定之出院後生活計畫的團體是屬於社會化團體","imageUrl":null},{"key":"D","text":"同性戀者聚在一起相互支持共同倡導與創造另一種生活型式的團體是屬於教育性團體","imageUrl":null}],"correctAnswer":"D","explanation":"這類涉及社會價值變革、權益倡導與相互支持的團體，更傾向於「社會行動」或支持性質的模式。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_023","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"會談過程是一種有順序、有目的的動態過程，下列那一項是開始階段的重要工作？\\n(A)會談之初，社會個案工作者通常會很清晰地告訴案主會談時間的長短，為下一次會談做準備\\n(B)社會個案工作者必須運用技巧將他與案主之間的互動引導到會談目的\\n(C)社會個案工作者在討論一般內容後，應把焦點放在特殊領域中做深入探討\\n(D)會談內容涉及之層面宜比較一般性，不激起太多情緒反應，鼓勵案主多想、多表達","tableData":null,"images":[],"options":[{"key":"A","text":"會談之初，社會個案工作者通常會很清晰地告訴案主會談時間的長短，為下一次會談做準備","imageUrl":null},{"key":"B","text":"社會個案工作者必須運用技巧將他與案主之間的互動引導到會談目的","imageUrl":null},{"key":"C","text":"社會個案工作者在討論一般內容後，應把焦點放在特殊領域中做深入探討","imageUrl":null},{"key":"D","text":"會談內容涉及之層面宜比較一般性，不激起太多情緒反應，鼓勵案主多想、多表達","imageUrl":null}],"correctAnswer":"B","explanation":"開始階段的核心在於釐清專業關係，並運用技巧將溝通聚焦於雙方共同設定的工作目標與目的。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_024","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列那一項不是靜態的社區能力？\\n(A)財務資本\\n(B)有形資本\\n(C)志願行為\\n(D)環境資本","tableData":null,"images":[],"options":[{"key":"A","text":"財務資本","imageUrl":null},{"key":"B","text":"有形資本","imageUrl":null},{"key":"C","text":"志願行為","imageUrl":null},{"key":"D","text":"環境資本","imageUrl":null}],"correctAnswer":"C","explanation":"志願行為屬於動態的社會參與與運作過程，而非如金錢、資產或自然資源等固定的資源資本。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_025","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"在專業關係中，不論個案所碰到的問題為何，或是做出何種行為，社會工作者都不應對案主的行為、情感、思想加以批評。下列何種情況符合以上陳述？\\n(A)服務兒虐加害者時，社工對案主說：「不管紀錄上怎麼寫，我想先聽聽你對這件事情的說法。」\\n(B)服務受到家庭暴力的婦女時，社工對該婦女說：「你怎麼不離開呢？」\\n(C)服務失業的個案時，社工對案主說：「你為什麼不去參加就業徵才活動？」\\n(D)進行婚姻諮商時，社工對案主說：「你們怎麼不想想孩子？」","tableData":null,"images":[],"options":[{"key":"A","text":"服務兒虐加害者時，社工對案主說：「不管紀錄上怎麼寫，我想先聽聽你對這件事情的說法。」","imageUrl":null},{"key":"B","text":"服務受到家庭暴力的婦女時，社工對該婦女說：「你怎麼不離開呢？」","imageUrl":null},{"key":"C","text":"服務失業的個案時，社工對案主說：「你為什麼不去參加就業徵才活動？」","imageUrl":null},{"key":"D","text":"進行婚姻諮商時，社工對案主說：「你們怎麼不想想孩子？」","imageUrl":null}],"correctAnswer":"A","explanation":"此做法表現了接納與非批判態度，讓案主有機會在不感到被指責的情況下，表達個人的觀點。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_026","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"在推動社區照顧的過程中，下列那一項不是政府政策應該優先考慮的？\\n(A)社區是否已經準備好擔負起部分的福利責任\\n(B)社區是否有做決定的自主性\\n(C)社區是否有服務使用者\\n(D)社區是否有民意代表的支持","tableData":null,"images":[],"options":[{"key":"A","text":"社區是否已經準備好擔負起部分的福利責任","imageUrl":null},{"key":"B","text":"社區是否有做決定的自主性","imageUrl":null},{"key":"C","text":"社區是否有服務使用者","imageUrl":null},{"key":"D","text":"社區是否有民意代表的支持","imageUrl":null}],"correctAnswer":"D","explanation":"社區照顧的核心在於服務主體、社區能量與自主參與，民意代表的政治支持並非服務規劃的首要考慮因素。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_027","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關團體衝突的敘述，下列何者錯誤？\\n(A)團體衝突不全然是一種團體失功能的現象\\n(B)團體衝突有時反而是一種能力的提升\\n(C)團體衝突是無可避免的\\n(D)團體衝突潛在的破壞性還是大於建設性","tableData":null,"images":[],"options":[{"key":"A","text":"團體衝突不全然是一種團體失功能的現象","imageUrl":null},{"key":"B","text":"團體衝突有時反而是一種能力的提升","imageUrl":null},{"key":"C","text":"團體衝突是無可避免的","imageUrl":null},{"key":"D","text":"團體衝突潛在的破壞性還是大於建設性","imageUrl":null}],"correctAnswer":"D","explanation":"衝突若能妥善處理，往往能增進團體韌性與建設性發展，其破壞性並不必然大於其成長價值。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_028","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關強制性團體的敘述，下列何者錯誤？\\n(A)又稱為非自治團體\\n(B)比較不考慮成員的期待\\n(C)精神科病患家屬所組成的團體是屬於此類型\\n(D)成員一開始容易表現沉默，甚至不合作的態度","tableData":null,"images":[],"options":[{"key":"A","text":"又稱為非自治團體","imageUrl":null},{"key":"B","text":"比較不考慮成員的期待","imageUrl":null},{"key":"C","text":"精神科病患家屬所組成的團體是屬於此類型","imageUrl":null},{"key":"D","text":"成員一開始容易表現沉默，甚至不合作的態度","imageUrl":null}],"correctAnswer":"C","explanation":"病患家屬團體多為基於共通需求的自願性參與，強制性團體則通常是依法律或機構命令參加。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_029","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關團體類型的敘述，下列何者錯誤？\\n(A)心理團體主要目的是要讓成員獲得情緒滿足與發展人際關係\\n(B)社會團體著重的是工作成效的展現\\n(C)心理團體一般較傾向同質性的成員組合\\n(D)社會團體一般來說傾向同質性的成員組合","tableData":null,"images":[],"options":[{"key":"A","text":"心理團體主要目的是要讓成員獲得情緒滿足與發展人際關係","imageUrl":null},{"key":"B","text":"社會團體著重的是工作成效的展現","imageUrl":null},{"key":"C","text":"心理團體一般較傾向同質性的成員組合","imageUrl":null},{"key":"D","text":"社會團體一般來說傾向同質性的成員組合","imageUrl":null}],"correctAnswer":"D","explanation":"社會團體常需結合具備不同專長或觀點的人員（異質性）以完成共同的工作任務與社會目標。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_030","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關社會個案工作者角色的敘述，下列何者錯誤？\\n(A)使能者／諮商者的角色：協助案主改變行為的使能者，積極透過傾聽、同理案主的情境，發揮諮商者的角色\\n(B)諮詢者／教育者的角色：提供案主專門知識或訊息的諮詢者，運用教導技巧協助案主如何瞭解和處理自己的問題\\n(C)調停者／仲介者的角色：當處理個案問題時，發現他們有因權利被剝奪而產生共同的問題，於是透過社會行動方式，促成問題解決\\n(D)個案管理者：當案主有複雜而嚴重的問題時，需要轉介或連結不同資源，並監督服務輸送，使嚴重問題得以改善","tableData":null,"images":[],"options":[{"key":"A","text":"使能者／諮商者的角色：協助案主改變行為的使能者，積極透過傾聽、同理案主的情境，發揮諮商者的角色","imageUrl":null},{"key":"B","text":"諮詢者／教育者的角色：提供案主專門知識或訊息的諮詢者，運用教導技巧協助案主如何瞭解和處理自己的問題","imageUrl":null},{"key":"C","text":"調停者／仲介者的角色：當處理個案問題時，發現他們有因權利被剝奪而產生共同的問題，於是透過社會行動方式，促成問題解決","imageUrl":null},{"key":"D","text":"個案管理者：當案主有複雜而嚴重的問題時，需要轉介或連結不同資源，並監督服務輸送，使嚴重問題得以改善","imageUrl":null}],"correctAnswer":"C","explanation":"調停者著重中立協商解決糾紛，促成社會行動來解決權利剝奪問題通常屬於倡導者或組織者的職責。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_031","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"目前在社區議題中推動的參與式預算，是屬於下列那一種理念的實踐？\\n(A)審議民主在社區參與的實踐\\n(B)社區需求在社區理念的實踐\\n(C)社區培力在社區能力的實踐\\n(D)社區服務在社區資源的實踐","tableData":null,"images":[],"options":[{"key":"A","text":"審議民主在社區參與的實踐","imageUrl":null},{"key":"B","text":"社區需求在社區理念的實踐","imageUrl":null},{"key":"C","text":"社區培力在社區能力的實踐","imageUrl":null},{"key":"D","text":"社區服務在社區資源的實踐","imageUrl":null}],"correctAnswer":"A","explanation":"參與式預算強調公民透過公開討論與審議程序，決定公共資源分配，是審議民主的具體落實。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_032","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關「治療會談」的敘述，下列何者正確？\\n(A)治療會談是在服務計畫確定後，較完整而有步驟地完成服務目標\\n(B)研判焦點問題後，提供案主所需之服務\\n(C)為了得到案主個人或社會問題的背景、問題史\\n(D)建立對事實的建構，以引導介入方向","tableData":null,"images":[],"options":[{"key":"A","text":"治療會談是在服務計畫確定後，較完整而有步驟地完成服務目標","imageUrl":null},{"key":"B","text":"研判焦點問題後，提供案主所需之服務","imageUrl":null},{"key":"C","text":"為了得到案主個人或社會問題的背景、問題史","imageUrl":null},{"key":"D","text":"建立對事實的建構，以引導介入方向","imageUrl":null}],"correctAnswer":"A","explanation":"治療會談具有高度目的性，旨在評估與計畫確立後，有系統地運用專業技術協助案主改善功能。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_033","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關婚姻暴力之敘述，下列何者錯誤？\\n(A)婚姻暴力事件的當事人並非全是低社經地位和族群的問題\\n(B)婚姻暴力的行為包括肢體暴力、性暴力和精神暴力\\n(C)婚姻暴力事件僅對當事人有影響\\n(D)國人在婚姻暴力事件後，尋求外界的協助多數以家人與朋友為主","tableData":null,"images":[],"options":[{"key":"A","text":"婚姻暴力事件的當事人並非全是低社經地位和族群的問題","imageUrl":null},{"key":"B","text":"婚姻暴力的行為包括肢體暴力、性暴力和精神暴力","imageUrl":null},{"key":"C","text":"婚姻暴力事件僅對當事人有影響","imageUrl":null},{"key":"D","text":"國人在婚姻暴力事件後，尋求外界的協助多數以家人與朋友為主","imageUrl":null}],"correctAnswer":"C","explanation":"婚姻暴力不僅影響配偶雙方，對同住的目睹兒童及其家庭關係、社區安全亦會產生負面連鎖反應。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_034","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"有關社會工作者在災害準備及災後生活重建各階段的角色與職責，下列敘述何者錯誤？\\n(A)在災難預防期，進行風險評估與防災教育\\n(B)在災難整備期，進行防災與救災人員的組訓與演練\\n(C)在災難應變期，治療罹患創傷後壓力症候群的災民\\n(D)在災後復原期，協助災民澄清對新家園的重建計畫，透過討論及交流將意見表達並完成重建","tableData":null,"images":[],"options":[{"key":"A","text":"在災難預防期，進行風險評估與防災教育","imageUrl":null},{"key":"B","text":"在災難整備期，進行防災與救災人員的組訓與演練","imageUrl":null},{"key":"C","text":"在災難應變期，治療罹患創傷後壓力症候群的災民","imageUrl":null},{"key":"D","text":"在災後復原期，協助災民澄清對新家園的重建計畫，透過討論及交流將意見表達並完成重建","imageUrl":null}],"correctAnswer":"C","explanation":"應變期首重生命救助與緊急物資安置，深層心理創傷（如 PTSD）的治療通常需延續至中長期復原階段。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_035","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"從學校社會工作者的倫理考量中，對國一小美的處遇下列何者較適切？\\n(A)小美有急需，可以依狀況借用金錢給她\\n(B)小美將於下課後找人對付小芳，考量與小美維持關係，可答應為其保守秘密\\n(C)告知少年保護官有關小美的最近缺課、打人的事實\\n(D)小美決定不再上學，基於案主自決原則予以尊重","tableData":null,"images":[],"options":[{"key":"A","text":"小美有急需，可以依狀況借用金錢給她","imageUrl":null},{"key":"B","text":"小美將於下課後找人對付小芳，考量與小美維持關係，可答應為其保守秘密","imageUrl":null},{"key":"C","text":"告知少年保護官有關小美的最近缺課、打人的事實","imageUrl":null},{"key":"D","text":"小美決定不再上學，基於案主自決原則予以尊重","imageUrl":null}],"correctAnswer":"C","explanation":"基於保密例外與公共安全，若案主涉及違法或危害他人之虞，社工有義務通報相關權責單位介入。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_036","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列何者無權聲請緊急保護令？\\n(A)被害人\\n(B)檢察官\\n(C)警察機關\\n(D)縣（市）主管機關","tableData":null,"images":[],"options":[{"key":"A","text":"被害人","imageUrl":null},{"key":"B","text":"檢察官","imageUrl":null},{"key":"C","text":"警察機關","imageUrl":null},{"key":"D","text":"縣（市）主管機關","imageUrl":null}],"correctAnswer":"A","explanation":"依我國法規，緊急保護令應由檢察官、警察機關或地方政府主管機關向法院聲請，而非由被害人直接聲請。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_037","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"Berry 所提出的文化適應模式中，移民者專注於適應新環境，只和主流文化建立關係，同時刻意拒絕自己原本的文化和傳統，這是下列那一種應對方式？\\n(A)邊緣化\\n(B)隔離\\n(C)同化\\n(D)整合","tableData":null,"images":[],"options":[{"key":"A","text":"邊緣化","imageUrl":null},{"key":"B","text":"隔離","imageUrl":null},{"key":"C","text":"同化","imageUrl":null},{"key":"D","text":"整合","imageUrl":null}],"correctAnswer":"C","explanation":"同化模式係指移民放棄母國文化特徵，轉而全盤接受並融入居住地主流社會的文化價值。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_038","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"身心障礙者就醫過程中，常會因各種因素而遇到阻礙，若因一些不被尊重、疏忽或貶抑等經驗之故，造成不信任醫療服務提供者，這是下列那一種面向的就醫障礙？\\n(A)態度\\n(B)表達意見\\n(C)資訊不對稱\\n(D)協調","tableData":null,"images":[],"options":[{"key":"A","text":"態度","imageUrl":null},{"key":"B","text":"表達意見","imageUrl":null},{"key":"C","text":"資訊不對稱","imageUrl":null},{"key":"D","text":"協調","imageUrl":null}],"correctAnswer":"A","explanation":"態度障礙源於外界（如醫療人員）對其存在的刻板印象、歧視或缺乏同理心，進而影響其求醫意願。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_039","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"若刑事被告或犯罪嫌疑人因精神障礙或其他心智缺陷無法為完全之陳述時，地方主管機關可聲請法院同意指派社會工作人員擔任下列何種協助角色？\\n(A)法定代理人\\n(B)出庭輔導人\\n(C)權利保障人\\n(D)訴訟輔佐人","tableData":null,"images":[],"options":[{"key":"A","text":"法定代理人","imageUrl":null},{"key":"B","text":"出庭輔導人","imageUrl":null},{"key":"C","text":"權利保障人","imageUrl":null},{"key":"D","text":"訴訟輔佐人","imageUrl":null}],"correctAnswer":"D","explanation":"訴訟輔佐人旨在協助欠缺陳述能力者在法庭上表達意見，以維護其訴訟程序上的權益。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_040","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"一般而言，身心障礙福利的政策模式，可分為社會福利與公民權利兩種模式，下列對於公民權利模式的敘述何者正確？\\n(A)障礙是社會排除的後果，而非個人身心缺陷的結果\\n(B)障礙意謂著缺陷，故個人無法以慣常的方式在社會上工作或生活\\n(C)障礙者的社會生活需求，必須以另外的管道來解決\\n(D)身障福利的取得基於資格認定而非法律保障","tableData":null,"images":[],"options":[{"key":"A","text":"障礙是社會排除的後果，而非個人身心缺陷的結果","imageUrl":null},{"key":"B","text":"障礙意謂著缺陷，故個人無法以慣常的方式在社會上工作或生活","imageUrl":null},{"key":"C","text":"障礙者的社會生活需求，必須以另外的管道來解決","imageUrl":null},{"key":"D","text":"身障福利的取得基於資格認定而非法律保障","imageUrl":null}],"correctAnswer":"A","explanation":"公民權利模式將障礙視為環境阻礙與不合理排除的產物，強調應透過社會變革來保障權利。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_041","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"評估兒童及少年的權益與福祉時，生態系統是常被應用的理論，下列那一項說明並不是以生態系統來評估兒童及少年的權益與福祉？\\n(A)評估時需考量兒童及少年的家庭所處的外部及鉅視系統\\n(B)辨識環境中的不利因素是評估時的重點之一\\n(C)界定遭遇困難的兒童及少年為問題的來源\\n(D)評估是一個過程而不是一個事件","tableData":null,"images":[],"options":[{"key":"A","text":"評估時需考量兒童及少年的家庭所處的外部及鉅視系統","imageUrl":null},{"key":"B","text":"辨識環境中的不利因素是評估時的重點之一","imageUrl":null},{"key":"C","text":"界定遭遇困難的兒童及少年為問題的來源","imageUrl":null},{"key":"D","text":"評估是一個過程而不是一個事件","imageUrl":null}],"correctAnswer":"C","explanation":"生態系統觀點強調個人與環境的互動，反對將問題完全歸咎於個人（受害者）本身。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_042","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"下列那一項是關於兒少受虐的錯誤認知？\\n(A)兒少受虐現象存在於各種社經背景的家庭中\\n(B)會虐待兒少者對所有人都會暴力相向\\n(C)男孩也可能是性虐待的受害者\\n(D)疏忽是兒少虐待的類型之一","tableData":null,"images":[],"options":[{"key":"A","text":"兒少受虐現象存在於各種社經背景的家庭中","imageUrl":null},{"key":"B","text":"會虐待兒少者對所有人都會暴力相向","imageUrl":null},{"key":"C","text":"男孩也可能是性虐待的受害者","imageUrl":null},{"key":"D","text":"疏忽是兒少虐待的類型之一","imageUrl":null}],"correctAnswer":"B","explanation":"虐待行為常具選擇性，施虐者可能僅對特定對象（如權力不對等的弱小兒童）展現暴力。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_043","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"如果一位保育人員發現小華（8 歲）的主要照顧者因罹患精神疾病，而影響了對小華的日常生活之照顧，此時這位保育人員可以進行下列那一種通報？\\n(A)兒少保護通報\\n(B)目睹兒少通報\\n(C)兒少自立生活通報\\n(D)脆弱家庭通報","tableData":null,"images":[],"options":[{"key":"A","text":"兒少保護通報","imageUrl":null},{"key":"B","text":"目睹兒少通報","imageUrl":null},{"key":"C","text":"兒少自立生活通報","imageUrl":null},{"key":"D","text":"脆弱家庭通報","imageUrl":null}],"correctAnswer":"D","explanation":"當家庭因遭逢重大傷病或變故導致功能受損、照顧不周時，應通報脆弱家庭以獲得預防性社會支持。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_044","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"我國老人福利已推動老人財產信託，下列那一項有關信託的敘述錯誤？\\n(A)信託是以「財產權」為中心的法律關係\\n(B)信託是老人保護的重要方法\\n(C)人格權、身心權可以做為財產信託\\n(D)專利權、著作權可以做為財產信託","tableData":null,"images":[],"options":[{"key":"A","text":"信託是以「財產權」為中心的法律關係","imageUrl":null},{"key":"B","text":"信託是老人保護的重要方法","imageUrl":null},{"key":"C","text":"人格權、身心權可以做為財產信託","imageUrl":null},{"key":"D","text":"專利權、著作權可以做為財產信託","imageUrl":null}],"correctAnswer":"C","explanation":"財產信託必須以具經濟價值的資產為標的，非財產性質的人格權或身心權利不屬於此範疇。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_045","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"施虐的父母也是來自受虐的成長過程，這是下列兒童虐待原因的何種模式之解釋？\\n(A)生態區位\\n(B)心理疾病\\n(C)家庭結構\\n(D)社會學習","tableData":null,"images":[],"options":[{"key":"A","text":"生態區位","imageUrl":null},{"key":"B","text":"心理疾病","imageUrl":null},{"key":"C","text":"家庭結構","imageUrl":null},{"key":"D","text":"社會學習","imageUrl":null}],"correctAnswer":"D","explanation":"社會學習理論指出暴力行為是透過觀察與自身經歷習得，導致虐待現象跨代傳遞。 ","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_046","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"醫務社會工作者對於需要危機處遇的病人，下列敘述何者錯誤？\\n(A)立即給予支持同理與傾聽，並且建立信任的專業關係\\n(B)透過會談以瞭解病患的危機因素，以及優先協助處理事項\\n(C)在會談中協助病患認識問題，由醫務社會工作者自行決定處遇策略\\n(D)持續協助病患，待任務完成評估出院或轉介服務","tableData":null,"images":[],"options":[{"key":"A","text":"立即給予支持同理與傾聽，並且建立信任的專業關係","imageUrl":null},{"key":"B","text":"透過會談以瞭解病患的危機因素，以及優先協助處理事項","imageUrl":null},{"key":"C","text":"在會談中協助病患認識問題，由醫務社會工作者自行決定處遇策略","imageUrl":null},{"key":"D","text":"持續協助病患，待任務完成評估出院或轉介服務","imageUrl":null}],"correctAnswer":"C","explanation":"即使在醫療危機中，仍應尊重案主的參與權與選擇權，並與其共同研商處遇方向。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_047","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"醫務社會工作者在實務所運用之社會醫療診斷模式，在臨床上常運用 4Rs 來檢視與評估個案之狀況，請問 4Rs 包含下列幾項？①角色（Roles） ②反應（Reactions） ③復原力（Resilience） ④關係（Relationships） ⑤資源（Resources）\\n(A)①②③④\\n(B)②③④⑤\\n(C)①③④⑤\\n(D)①②④⑤","tableData":null,"images":[],"options":[{"key":"A","text":"①②③④","imageUrl":null},{"key":"B","text":"②③④⑤","imageUrl":null},{"key":"C","text":"①③④⑤","imageUrl":null},{"key":"D","text":"①②④⑤","imageUrl":null}],"correctAnswer":"D","explanation":"4Rs 臨床評估工具包含：Roles（角色）、Reactions（反應）、Relationships（關係）與 Resources（資源）。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_048","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"關於我國托育服務與相關政策，下列敘述何者正確？\\n(A)「照顧」是托育服務的首要工作，「教育」則是托育服務的附帶功能\\n(B)托育服務是一種替代父母照顧的兒童照顧方案\\n(C)居家式托育服務提供者若是住在隔壁的鄰居，不需要額外範定其法定資格\\n(D)在我國的幼托整合政策中，將「幼兒園」依收托年齡分為「幼稚園」及「托兒所」","tableData":null,"images":[],"options":[{"key":"A","text":"「照顧」是托育服務的首要工作，「教育」則是托育服務的附帶功能","imageUrl":null},{"key":"B","text":"托育服務是一種替代父母照顧的兒童照顧方案","imageUrl":null},{"key":"C","text":"居家式托育服務提供者若是住在隔壁的鄰居，不需要額外範定其法定資格","imageUrl":null},{"key":"D","text":"在我國的幼托整合政策中，將「幼兒園」依收托年齡分為「幼稚園」及「托兒所」","imageUrl":null}],"correctAnswer":"B","explanation":"托育服務的主要目的是在父母外出工作或無法看顧時，提供替代性的安全照顧與支持系統。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_049","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"關於家庭社會工作的敘述，下列何者錯誤？\\n(A)在方法上，是以家庭為整體實施的社會工作\\n(B)在對象上，以服務家庭中有問題的成員為主\\n(C)在評估上，包含整個家庭及其成員\\n(D)在內容上，提供各項家庭服務","tableData":null,"images":[],"options":[{"key":"A","text":"在方法上，是以家庭為整體實施的社會工作","imageUrl":null},{"key":"B","text":"在對象上，以服務家庭中有問題的成員為主","imageUrl":null},{"key":"C","text":"在評估上，包含整個家庭及其成員","imageUrl":null},{"key":"D","text":"在內容上，提供各項家庭服務","imageUrl":null}],"correctAnswer":"B","explanation":"家庭社工視家庭為一個互動系統，著重整體家庭的功能與連結，而非僅針對單一「標籤化」成員。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_050","category":"economics","stageId":"111_111010_502","type":"multiple-choice","difficulty":2,"text":"就生態觀點（ecological perspective）分析，小明的母親常年凌晨 4 點到 9 點在早餐店工作，其母親工作的時間、型態等對小明而言是屬於下列何者？\\n(A)微視系統（micro-system）\\n(B)中介系統（meso-system）\\n(C)外在系統（exo-system）\\n(D)鉅視系統（macro-system）","tableData":null,"images":[],"options":[{"key":"A","text":"微視系統（micro-system）","imageUrl":null},{"key":"B","text":"中介系統（meso-system）","imageUrl":null},{"key":"C","text":"外在系統（exo-system）","imageUrl":null},{"key":"D","text":"鉅視系統（macro-system）","imageUrl":null}],"correctAnswer":"C","explanation":"外在系統係指個人未直接參與，但該環境發生的事件會影響其所在環境（如父母的工作環境）。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","502","社會行政","社會工作大意","測驗題"],"certificationType":"111年公務人員初等考試"}]');export{e as default};
